from __future__ import annotations

DND_MINI_APP_HTML = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#100a18"><title>Kira D&D</title><script src="https://telegram.org/js/telegram-web-app.js"></script><style>:root{font-family:Inter,system-ui;color-scheme:dark;--bg:#0d0915;--card:#1c1328;--line:#513968;--a:#c38aff;--mut:#c4b2d2}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#693b8055,transparent 34%),var(--bg);color:white;padding:14px}.wrap{max-width:720px;margin:auto}.card{background:#1c1328e8;border:1px solid var(--line);border-radius:22px;padding:16px;margin-bottom:12px;box-shadow:0 18px 45px #0005}.mut{color:var(--mut)}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px}label{display:block;color:var(--mut);font-size:13px;margin:9px 0}input,textarea{width:100%;margin-top:5px;padding:12px;border:1px solid var(--line);border-radius:13px;background:#100a18;color:white;font:inherit}textarea{min-height:90px}button{border:0;border-radius:13px;padding:12px 14px;background:var(--a);font-weight:850;color:#160c20}.dice{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.dice button{background:#110a19;color:var(--a);border:1px solid var(--line)}#result{text-align:center;font-size:30px;font-weight:900;padding:13px}.notice{padding:11px;border-radius:12px;background:#ffffff0a;color:var(--mut);margin:8px 0}@media(max-width:430px){.row{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><div class="mut">KIRA 1.6 · отдельный модуль</div><h1>🐉 D&D</h1><div class="mut">D&D отделён от основного Mini App, поэтому его сбой не уронит интерфейс Киры.</div></div><div id="notice" class="notice" style="display:none"></div><div class="card"><h2>🧙 Герой</h2><div class="row"><label>Имя<input id="name"></label><label>Уровень<input id="level" type="number" min="1" max="20"></label></div><div class="row"><label>Раса<input id="race"></label><label>Класс<input id="klass"></label></div><div class="row"><label>HP<input id="hp" type="number"></label><label>AC<input id="ac" type="number"></label></div><label>Заметки<textarea id="notes"></textarea></label><button onclick="save()">💾 Сохранить</button></div><div class="card"><h2>🎲 Кубы</h2><div class="dice"><button onclick="roll(4)">d4</button><button onclick="roll(6)">d6</button><button onclick="roll(8)">d8</button><button onclick="roll(10)">d10</button><button onclick="roll(12)">d12</button><button onclick="roll(20)">d20</button><button onclick="roll(100)">d100</button></div><div id="result">—</div></div><div class="card"><h2>🗺 Кампании</h2><div class="row"><input id="camp" placeholder="Название"><button onclick="createCamp()">Создать</button></div><div class="row" style="margin-top:8px"><input id="code" placeholder="Код"><button onclick="joinCamp()">Войти</button></div><div id="camps"></div></div></div><script>const tg=window.Telegram?.WebApp;tg?.ready();tg?.expand();const init=tg?.initData||'',H={'X-Telegram-Init-Data':init,'Content-Type':'application/json'},$=x=>document.getElementById(x);let state={};async function api(u,o={}){o.headers={...H,...(o.headers||{})};let r=await fetch(u,o);if(!r.ok)throw new Error(await r.text());return r.json()}async function load(){if(!init){$('notice').style.display='block';$('notice').textContent='Открой D&D кнопкой /dnd в Telegram.';return}try{state=await api('/api/dnd/character');$('name').value=state.name||'';$('level').value=state.level||1;$('race').value=state.race||'';$('klass').value=state.class||'';$('hp').value=state.hp??10;$('ac').value=state.ac??10;$('notes').value=state.notes||'';camps()}catch(e){$('notice').style.display='block';$('notice').textContent='D&D API недоступен'}}async function save(){try{state={...state,name:$('name').value,level:+$('level').value||1,race:$('race').value,class:$('klass').value,hp:+$('hp').value||0,ac:+$('ac').value||0,notes:$('notes').value};await api('/api/dnd/character',{method:'PUT',body:JSON.stringify(state)});alert('Сохранено')}catch(e){alert('Ошибка сохранения')}}async function roll(s){try{let d=await api('/api/dnd/roll',{method:'POST',body:JSON.stringify({sides:s,modifier:0,mode:'normal'})});$('result').textContent=d.result+' · '+d.expression}catch(e){$('result').textContent='Ошибка'}}async function camps(){try{let a=await api('/api/dnd/campaigns');$('camps').innerHTML=a.length?a.map(x=>'<div class="notice"><b>'+x.name+'</b><br>код '+x.code+'</div>').join(''):'<div class="notice">Пока нет кампаний.</div>'}catch(e){$('camps').textContent='Ошибка'}}async function createCamp(){try{let d=await api('/api/dnd/campaigns',{method:'POST',body:JSON.stringify({name:$('camp').value||'Новая кампания'})});alert('Код: '+d.code);camps()}catch(e){alert('Ошибка')}}async function joinCamp(){try{await api('/api/dnd/campaigns/join',{method:'POST',body:JSON.stringify({code:$('code').value.trim()})});camps()}catch(e){alert('Код не найден')}}load();</script></body></html>'''
